using System;using System.IO;using System.Collections.Generic;using UnityEngine;using Object=UnityEngine.Object;
public static class ValidateShopAccess {
 public static string Main(){if(!Application.isPlaying)throw new Exception("Play Mode required");var shop=GameObject.Find("New_Map").transform.Find("11_Five_Hangar_Farm/S - Farm supplies and cottage/Farm supplies shop");var go=new GameObject("Temporary shop accessibility walker");var cc=go.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.3f;cc.center=new Vector3(0,.9f,0);cc.skinWidth=.025f;int passed=0,failed=0;var report=new List<string>();Action<bool,string> check=(ok,s)=>{report.Add((ok?"PASS ":"FAIL ")+s);if(ok)passed++;else failed++;};try{foreach(int side in new[]{-1,1}){cc.enabled=false;go.transform.position=shop.TransformPoint(new Vector3(side*4.15f,.19f,6));cc.enabled=true;Physics.SyncTransforms();cc.Move(shop.TransformVector(new Vector3(0,0,-7.1f)));var p=shop.InverseTransformPoint(go.transform.position);check(p.z<-.7f,"Side aisle "+side+" is accessible past the counter");cc.Move(shop.TransformVector(new Vector3(-side*4.15f,0,0)));p=shop.InverseTransformPoint(go.transform.position);check(Mathf.Abs(p.x)<.5f,"Rear shop floor reachable from aisle "+side);}
 cc.enabled=false;go.transform.position=shop.TransformPoint(new Vector3(0,.19f,5));cc.enabled=true;cc.Move(shop.TransformVector(new Vector3(0,0,-7)));check(shop.InverseTransformPoint(go.transform.position).z>2.6f,"Lowered counter retains solid collision");
 var hits=Physics.RaycastAll(shop.TransformPoint(new Vector3(0,1.6f,4)),-shop.forward,7);check(Array.FindIndex(hits,h=>h.transform.IsChildOf(shop)&&Vector3.Distance(h.point,shop.TransformPoint(new Vector3(0,1.6f,2.1f)))<.7f)<0,"Player eye line clears the counter top");
 }finally{Object.DestroyImmediate(go);}string text=passed+" passed, "+failed+" failed\n"+string.Join("\n",report);File.WriteAllText("output/NewMap/FinishedShop/access-validation.txt",text);return text;}
}
